"use strict";const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));let data={updates:[]};function render(){const q=$('#search').value.toLowerCase(),p=$('#product').value;const list=data.updates.filter(x=>(!p||x.product===p)&&(!q||JSON.stringify(x).toLowerCase().includes(q)));const groups=Map.groupBy(list,x=>x.product);$('#content').innerHTML=[...groups].map(([product,rows])=>`<section class="product"><h2>${esc(product)}</h2>${[...Map.groupBy(rows,x=>x.featureVersion)].map(([version,items])=>`<section class="version"><h3>Version ${esc(version)}</h3><div class="grid">${items.map(x=>`<article class="card"><span class="badge">${esc(x.updateType)}</span><h4>${esc(x.kb)}</h4><p>${new Date(x.releaseDate+'T00:00:00Z').toLocaleDateString('en-US')}</p><p>OS Build: ${esc(x.osBuilds.join(', '))}</p><a class="doc" href="${esc(x.documentationUrl)}" target="_blank" rel="noopener noreferrer">Microsoft documentation ↗</a></article>`).join('')}</div></section>`).join('')}</section>`).join('')||'<p>No matching updates.</p>'}fetch('data/updates.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(x=>{data=x;[...new Set(x.updates.map(y=>y.product))].sort().forEach(y=>$('#product').add(new Option(y,y)));$('#sync').textContent=`Microsoft synchronization: ${new Date(x.generatedAt).toLocaleString('en-US')}${x.sourceErrors.length?` · ${x.sourceErrors.length} source errors`:''}`;render()}).catch(()=>{$('#sync').className='error';$('#sync').textContent='Live data could not be loaded.'});['search','product'].forEach(x=>$('#'+x).addEventListener('input',render));$('#theme').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));